//go:build e2e

package e2e

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"

	// Import agents package to trigger init() registration.
	_ "github.com/entireio/external-agents/e2e/agents"
	"github.com/entireio/external-agents/e2e/entire"
	"github.com/entireio/external-agents/e2e/testutil"
)

func TestMain(m *testing.M) {
	tmpDir, err := os.MkdirTemp("", "e2e-agents-*")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to create temp dir: %v\n", err)
		os.Exit(1)
	}
	defer os.RemoveAll(tmpDir)

	discoveredAgents, err := DiscoverAgents()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to discover agents: %v\n", err)
		os.Exit(1)
	}

	if len(discoveredAgents) == 0 {
		fmt.Fprintln(os.Stderr, "no agents found in agents/ directory")
		os.Exit(1)
	}

	for _, agentDir := range discoveredAgents {
		agentName := filepath.Base(agentDir)
		fmt.Printf("Building %s...\n", agentName)
		binPath, err := BuildAgent(agentName, tmpDir)
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to build %s: %v\n", agentName, err)
			os.Exit(1)
		}
		AgentBinaries[agentName] = binPath
		fmt.Printf("Built %s -> %s\n", agentName, binPath)
	}

	// Add the temp bin directory to PATH so that `entire enable` can discover
	// the agent binaries (e.g. entire-agent-kiro) during lifecycle tests.
	os.Setenv("PATH", tmpDir+string(os.PathListSeparator)+os.Getenv("PATH"))

	// --- Artifact directory setup ---
	runDir := os.Getenv("E2E_ARTIFACT_DIR")
	if runDir == "" {
		_, file, _, _ := runtime.Caller(0)
		testutil.ArtifactRoot = filepath.Join(filepath.Dir(file), "artifacts")
		runDir = testutil.ArtifactRunDir()
	}
	_ = os.MkdirAll(runDir, 0o755)
	testutil.SetRunDir(runDir)

	// Prepend the entire binary's directory to PATH so git hooks resolve
	// to the same binary the test harness uses.
	entireBin := entire.BinPath()
	if dir := filepath.Dir(entireBin); dir != "." {
		os.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	}

	// --- Preflight checks ---
	if _, err := exec.LookPath("tmux"); err != nil {
		fmt.Fprintln(os.Stderr, "warning: tmux not found — interactive session tests will fail")
	}

	// Write entire version info to artifact dir.
	version := "unknown"
	if out, err := exec.Command(entireBin, "version").Output(); err == nil {
		version = string(out)
	}
	preflight := fmt.Sprintf("entire binary:  %s\nentire version: %s\n", entireBin, version)
	_ = os.WriteFile(filepath.Join(runDir, "entire-version.txt"), []byte(preflight), 0o644)

	// Isolate git config to prevent user's ~/.gitconfig from interfering.
	os.Setenv("GIT_CONFIG_GLOBAL", "/dev/null")

	os.Exit(m.Run())
}

package kiro

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/external-agents/agents/entire-agent-kiro/internal/protocol"
)

func TestDetectUsesRepoRoot(t *testing.T) {
	t.Setenv("ENTIRE_REPO_ROOT", t.TempDir())

	ag := New()
	if ag.Detect().Present {
		t.Fatal("detect should be false when .kiro is absent")
	}

	kiroDir := filepath.Join(protocol.RepoRoot(), ".kiro")
	if err := os.MkdirAll(kiroDir, 0o750); err != nil {
		t.Fatalf("mkdir .kiro: %v", err)
	}

	if !ag.Detect().Present {
		t.Fatal("detect should be true when .kiro is present")
	}
}

func TestReadSessionLoadsNativeData(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	sessionRef := filepath.Join(repoRoot, ".entire", "tmp", "session-123.json")
	wantData := []byte(`{"conversation_id":"session-123","history":[]}`)
	if err := os.MkdirAll(filepath.Dir(sessionRef), 0o750); err != nil {
		t.Fatalf("mkdir session dir: %v", err)
	}
	if err := os.WriteFile(sessionRef, wantData, 0o600); err != nil {
		t.Fatalf("write session ref: %v", err)
	}

	got, err := New().ReadSession(&protocol.HookInputJSON{
		SessionID:  "session-123",
		SessionRef: sessionRef,
	})
	if err != nil {
		t.Fatalf("ReadSession() error = %v", err)
	}

	if got.SessionID != "session-123" {
		t.Fatalf("session_id = %q, want %q", got.SessionID, "session-123")
	}
	if got.AgentName != "kiro" {
		t.Fatalf("agent_name = %q, want %q", got.AgentName, "kiro")
	}
	if got.RepoPath != repoRoot {
		t.Fatalf("repo_path = %q, want %q", got.RepoPath, repoRoot)
	}
	if got.SessionRef != sessionRef {
		t.Fatalf("session_ref = %q, want %q", got.SessionRef, sessionRef)
	}
	if string(got.NativeData) != string(wantData) {
		t.Fatalf("native_data = %q, want %q", string(got.NativeData), string(wantData))
	}
	if got.ModifiedFiles == nil || got.NewFiles == nil || got.DeletedFiles == nil {
		t.Fatal("file lists should be initialized")
	}
}

func TestReadSessionReturnsErrorWhenTranscriptReadFails(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	_, err := New().ReadSession(&protocol.HookInputJSON{
		SessionID:  "session-123",
		SessionRef: filepath.Join(repoRoot, ".entire", "tmp", "missing.json"),
	})

	if err == nil || !strings.Contains(err.Error(), "failed to read transcript") {
		t.Fatalf("ReadSession() error = %v, want failed to read transcript", err)
	}
}

func TestWriteSessionPersistsNativeData(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
	t.Setenv("ENTIRE_CLI_VERSION", "7.8.9")

	sessionRef := filepath.Join(repoRoot, ".entire", "tmp", "session-456.json")
	wantData := []byte(`{"conversation_id":"session-456","history":[]}`)

	err := New().WriteSession(protocol.AgentSessionJSON{
		SessionID:  "session-456",
		AgentName:  "kiro",
		RepoPath:   repoRoot,
		SessionRef: sessionRef,
		NativeData: wantData,
	})
	if err != nil {
		t.Fatalf("WriteSession() error = %v", err)
	}

	gotData, err := os.ReadFile(sessionRef)
	if err != nil {
		t.Fatalf("read session ref: %v", err)
	}
	var got kiroTranscript
	if err := json.Unmarshal(gotData, &got); err != nil {
		t.Fatalf("parse written session: %v", err)
	}
	if got.ConversationID != "session-456" || got.CLIVersion != "7.8.9" {
		t.Fatalf("written transcript = %+v, want conversation/session version preserved", got)
	}
}

func TestFormatResumeCommand(t *testing.T) {
	if got := New().FormatResumeCommand("anything"); got != "kiro-cli chat --resume" {
		t.Fatalf("FormatResumeCommand() = %q, want %q", got, "kiro-cli chat --resume")
	}
}

package amp

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/external-agents/agents/entire-agent-amp/internal/protocol"
)

func TestInfo(t *testing.T) {
	agent := New()
	info := agent.Info()
	if info.ProtocolVersion != protocol.ProtocolVersion {
		t.Fatalf("ProtocolVersion = %d, want %d", info.ProtocolVersion, protocol.ProtocolVersion)
	}
	if info.Name != "amp" {
		t.Fatalf("Name = %q, want amp", info.Name)
	}
	if !info.Capabilities.Hooks || !info.Capabilities.TranscriptAnalyzer || !info.Capabilities.CompactTranscript {
		t.Fatalf("unexpected capabilities: %+v", info.Capabilities)
	}
	if !info.Capabilities.TranscriptPreparer {
		t.Fatalf("expected transcript_preparer capability")
	}
	if !info.Capabilities.TokenCalculator {
		t.Fatalf("expected token_calculator capability")
	}
}

func TestParseHookSessionStart(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", root)
	runner := &fakeCommandRunner{}
	agent := &Agent{CommandRunner: runner}
	event, err := agent.ParseHook("session.start", []byte(`{"type":"session.start","thread_id":"T-123"}`))
	if err != nil {
		t.Fatal(err)
	}
	if event == nil || event.Type != 1 || event.SessionID != "T-123" {
		t.Fatalf("event = %+v", event)
	}
	if event.Model != "claude" {
		t.Fatalf("Model = %q, want claude", event.Model)
	}
	assertExportedThread(t, runner, root)
}

func TestParseHookAgentStartFallbackExports(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", root)
	runner := &fakeCommandRunner{}
	agent := &Agent{CommandRunner: runner}
	event, err := agent.ParseHook("agent.start", []byte(`{"type":"agent.start","thread_id":"T-123","message":"hello"}`))
	if err != nil {
		t.Fatal(err)
	}
	if event == nil || event.Type != 2 || event.Prompt != "hello" {
		t.Fatalf("event = %+v", event)
	}
	if event.Model != "claude" {
		t.Fatalf("Model = %q, want claude", event.Model)
	}
	assertExportedThread(t, runner, root)
}

func TestParseHookAgentStartSkipsExportWhenPrepared(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", root)
	path := filepath.Join(root, ".entire", "tmp", "amp", "T-123.jsonl")
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(testPreparedTranscriptJSON), 0o600); err != nil {
		t.Fatal(err)
	}
	runner := &fakeCommandRunner{}
	agent := &Agent{CommandRunner: runner}
	event, err := agent.ParseHook("agent.start", []byte(`{"type":"agent.start","thread_id":"T-123","message":"hello"}`))
	if err != nil {
		t.Fatal(err)
	}
	if event == nil || event.Model != "claude" || event.Prompt != "hello" {
		t.Fatalf("event = %+v", event)
	}
	if runner.threadID != "" {
		t.Fatalf("expected no export, got threadID = %q", runner.threadID)
	}
}

func TestParseHookAgentEndWritesTranscript(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", root)
	runner := &fakeCommandRunner{}
	agent := &Agent{CommandRunner: runner}
	payload := `{"type":"agent.end","thread_id":"T-123","status":"done","messages":[{"role":"assistant","id":"a1","content":[{"type":"text","text":"done"}]}],"modified_files":["hello.txt"]}`
	event, err := agent.ParseHook("agent.end", []byte(payload))
	if err != nil {
		t.Fatal(err)
	}
	if event == nil || event.Type != 3 || event.SessionID != "T-123" || event.SessionRef == "" {
		t.Fatalf("event = %+v", event)
	}
	if event.Model != "claude" {
		t.Fatalf("Model = %q, want claude", event.Model)
	}
	assertExportedThread(t, runner, root)
}

func TestParseHookUsesSessionRefExportedThreadModel(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", root)
	path := filepath.Join(root, ".entire", "tmp", "amp", "T-123.jsonl")
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(testPreparedTranscriptJSON), 0o600); err != nil {
		t.Fatal(err)
	}
	runner := &fakeCommandRunner{}
	agent := &Agent{CommandRunner: runner}
	event, err := agent.ParseHook("session.start", []byte(`{"type":"session.start","thread_id":"T-123"}`))
	if err != nil {
		t.Fatal(err)
	}
	if event == nil || event.Model != "claude" {
		t.Fatalf("event = %+v", event)
	}
	if runner.threadID != "T-123" {
		t.Fatalf("export threadID = %q, want T-123", runner.threadID)
	}
}

func assertExportedThread(t *testing.T, runner *fakeCommandRunner, root string) {
	t.Helper()
	if runner.threadID != "T-123" {
		t.Fatalf("threadID = %q, want T-123", runner.threadID)
	}
	wantPath := filepath.Join(root, ".entire", "tmp", "amp", "T-123.jsonl")
	if runner.outputPath != wantPath {
		t.Fatalf("outputPath = %q, want %q", runner.outputPath, wantPath)
	}
	data, err := os.ReadFile(wantPath)
	if err != nil {
		t.Fatal(err)
	}
	if string(data) != testPreparedTranscriptJSON {
		t.Fatalf("exported data = %s", data)
	}
}

func TestGeneratePlugin(t *testing.T) {
	plugin := generatePlugin()
	for _, snippet := range []string{
		`PluginAPI`,
		`from "@ampcode/plugin"`,
		`amp.on("agent.start"`,
		`amp.on("agent.end"`,
		`["hooks", "amp", hookName]`,
		`toolCallsInMessages`,
		`amp.logger.log`,
		`maxBuffer: Infinity`,
	} {
		if !strings.Contains(plugin, snippet) {
			t.Fatalf("plugin missing %q\n%s", snippet, plugin)
		}
	}
}

func TestInstallAndUninstallHooks(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", root)
	agent := New()
	if agent.AreHooksInstalled() {
		t.Fatal("hooks should not be installed")
	}
	count, err := agent.InstallHooks(false, false)
	if err != nil {
		t.Fatal(err)
	}
	if count != 3 {
		t.Fatalf("count = %d, want 3", count)
	}
	if !agent.AreHooksInstalled() {
		t.Fatal("hooks should be installed")
	}
	count, err = agent.InstallHooks(false, false)
	if err != nil {
		t.Fatal(err)
	}
	if count != 0 {
		t.Fatalf("idempotent count = %d, want 0", count)
	}
	if err := agent.UninstallHooks(); err != nil {
		t.Fatal(err)
	}
	if agent.AreHooksInstalled() {
		t.Fatal("hooks should not be installed")
	}
}

func TestSafeSessionID(t *testing.T) {
	if got := safeSessionID("T/foo:bar"); got != "T_foo_bar" {
		t.Fatalf("safeSessionID = %q", got)
	}
}

package kiro

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func withRuntimeGOOS(t *testing.T, goos string) {
	t.Helper()
	previous := runtimeGOOS
	runtimeGOOS = goos
	t.Cleanup(func() {
		runtimeGOOS = previous
	})
}

func TestInstallHooksWritesCLIAndIDEHooksAndTrustedCommands(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	count, err := New().InstallHooks(false, false)
	if err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}
	if count != 9 {
		t.Fatalf("InstallHooks() count = %d, want %d", count, 9)
	}

	cliPath := filepath.Join(repoRoot, ".kiro", "agents", "entire.json")
	if _, err := os.Stat(cliPath); err != nil {
		t.Fatalf("expected CLI hook file at %s: %v", cliPath, err)
	}

	idePath := filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.kiro.hook")
	if _, err := os.Stat(idePath); err != nil {
		t.Fatalf("expected IDE hook file at %s: %v", idePath, err)
	}

	settingsPath := filepath.Join(repoRoot, ".vscode", "settings.json")
	data, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Fatalf("read settings.json: %v", err)
	}
	var settings map[string][]string
	if err := json.Unmarshal(data, &settings); err != nil {
		t.Fatalf("unmarshal settings.json: %v", err)
	}
	commands := settings["kiroAgent.trustedCommands"]
	if len(commands) != 1 || commands[0] != "sh -c 'entire hooks *" {
		t.Fatalf("trusted commands = %#v, want [\"sh -c 'entire hooks *\"]", commands)
	}
}

func TestInstallHooksIsIdempotentUnlessForced(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	if _, err := New().InstallHooks(false, false); err != nil {
		t.Fatalf("first InstallHooks() error = %v", err)
	}

	count, err := New().InstallHooks(false, false)
	if err != nil {
		t.Fatalf("second InstallHooks() error = %v", err)
	}
	if count != 0 {
		t.Fatalf("second InstallHooks() count = %d, want %d", count, 0)
	}

	count, err = New().InstallHooks(false, true)
	if err != nil {
		t.Fatalf("forced InstallHooks() error = %v", err)
	}
	if count != 9 {
		t.Fatalf("forced InstallHooks() count = %d, want %d", count, 9)
	}
}

func TestInstallHooksLocalDevUsesLocalCommands(t *testing.T) {
	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	if _, err := New().InstallHooks(true, false); err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	cliPath := filepath.Join(repoRoot, ".kiro", "agents", "entire.json")
	cliData, err := os.ReadFile(cliPath)
	if err != nil {
		t.Fatalf("read cli hooks: %v", err)
	}
	if !strings.Contains(string(cliData), `go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro stop`) {
		t.Fatalf("cli hooks = %s", cliData)
	}

	idePath := filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.kiro.hook")
	ideData, err := os.ReadFile(idePath)
	if err != nil {
		t.Fatalf("read ide hook: %v", err)
	}
	if !strings.Contains(string(ideData), `go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro stop`) {
		t.Fatalf("ide hook = %s", ideData)
	}

	settingsPath := filepath.Join(repoRoot, ".vscode", "settings.json")
	settingsData, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Fatalf("read settings: %v", err)
	}
	if !strings.Contains(string(settingsData), `go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks *`) {
		t.Fatalf("settings = %s", settingsData)
	}
}

func TestInstallHooksWritesWindowsCommandsAndTrustedCommands(t *testing.T) {
	withRuntimeGOOS(t, "windows")

	repoRoot := t.TempDir()
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)

	if _, err := New().InstallHooks(false, false); err != nil {
		t.Fatalf("InstallHooks() error = %v", err)
	}

	idePath := filepath.Join(repoRoot, ".kiro", "hooks", "entire-stop.kiro.hook")
	ideData, err := os.ReadFile(idePath)
	if err != nil {
		t.Fatalf("read ide hook: %v", err)
	}
	if strings.Contains(string(ideData), "sh -c") {
		t.Fatalf("windows ide hook should not use sh wrapper: %s", ideData)
	}
	if !strings.Contains(string(ideData), `"command": "cmd /c \"entire hooks kiro stop <NUL\""`) {
		t.Fatalf("windows ide hook should wrap with cmd /c and redirect stdin from NUL: %s", ideData)
	}

	settingsPath := filepath.Join(repoRoot, ".vscode", "settings.json")
	settingsData, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Fatalf("read settings: %v", err)
	}
	if !strings.Contains(string(settingsData), `"cmd /c \"entire hooks *"`) {
		t.Fatalf("windows settings should trust cmd /c wrapper glob: %s", settingsData)
	}
}

func TestInstallHooksLocalDevWindowsUsesPercentEnvVar(t *testing.T) {
	withRuntimeGOOS(t, "windows")

	repoRoot := t.TempDir()
