	if !strings.Contains(string(ideData), `"command": "cmd /c \"go run %KIRO_PROJECT_DIR%/cmd/entire/main.go hooks kiro stop <NUL\""`) {
		t.Fatalf("windows local-dev ide hook should wrap with cmd /c and redirect stdin: %s", ideData)
