	t.Run("read-transcript", func(t *testing.T) {
		var stdout bytes.Buffer
		err := HandleReadTranscript([]string{"--session-ref", "/tmp/repo/.entire/tmp/abc123.json"}, &stdout, testTranscriptReader{
			data: []byte(`{"conversation_id":"abc123"}`),
